        correct: 0,
        explanation: { correct: 'La posici\u00f3n geogr\u00e1fica privilegiada en la intersecci\u00f3n es la causa principal.', wrongs: ['La cercan\u00eda al ecuador no es el factor principal.', 'Los r\u00edos no son mencionados.', 'Las costas no son identificadas como factor principal.'] }
